// Keeps ProjectYearEnd working offline after the first visit. Generated by build.py; edit it there.
const CACHE = 'projectyearend-8e1513e66baa';
const FILES = ["./index.html", "./manifest.webmanifest", "./icons/icon-192.png", "./icons/icon-512.png", "./icons/icon-maskable-512.png", "./icons/apple-touch-icon.png"];

self.addEventListener('install', (event) => {
  // 'reload' skips the browser's own HTTP cache, so a new version never stores the previous index.html.
  const fresh = FILES.map((file) => new Request(file, { cache: 'reload' }));
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(fresh)).then(() => self.skipWaiting()));
});

// A new build has a new cache name, so the previous copy is removed once this one is ready.
self.addEventListener('activate', (event) => {
  event.waitUntil(caches.keys()
    .then((keys) => Promise.all(keys.filter((key) => key.startsWith('projectyearend-') && key !== CACHE).map((key) => caches.delete(key))))
    .then(() => self.clients.claim()));
});

// The app is one page, so every page request is answered from the cache and works without internet.
self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
  const cached = request.mode === 'navigate' ? caches.match('./index.html') : caches.match(request, { ignoreSearch: true });
  event.respondWith(cached.then((response) => response || fetch(request)));
});
